import type { ThemeItem, ThemeTier } from '../theme'
import { card, n, type L11 } from './card'

function step(
  id: string,
  tier: ThemeTier,
  from: L11,
  next: L11,
  flow: L11,
  flowKey: string,
  note: L11,
): ThemeItem[] {
  return [
    card(`nx-${id}`, 'stepToNext', tier, from, next, `n-${id}`, note),
    card(`pv-${id}`, 'nextToStep', tier, next, from, `p-${id}`, note),
    card(`fl-${id}`, 'stepToFlow', tier, from, flow, flowKey, note),
  ]
}

